def parse_range(s):
    if s.isdigit():
        return [int(s)]
    elif '-' in s:
        parts = s.split('-')
        if len(parts) != 2:
            raise ValueError("Invalid range format")
        start, end = parts
        if not start.isdigit() or not end.isdigit():
            raise ValueError("Invalid range format")
        start, end = int(start), int(end)
        if start > end:
            raise ValueError("Invalid range: start > end")
        return list(range(start, end + 1))
    else:
        raise ValueError("Invalid range format")
